use super::{Engine, Res, export, rq};

pub type Handler = fn(&mut Engine, &Json) -> Res;

#[derive(Clone, Copy, PartialEq, Eq)]
pub enum K {
    Undo,
    Plain,
    Query,
    Front,
    Todo,
}

pub struct Cmd {
    pub id: &'static str,
    pub label: &'static str,
    pub menu: &'static str,
    pub key: &'static str,
    pub params: &'static str,
    pub kind: K,
    pub run: Handler,
    pub undo: bool,
    pub query: bool,
}

const fn c(id: &'static str, label: &'static str, menu: &'static str, key: &'static str, params: &'static str, kind: K, run: Handler) -> Cmd {
    Cmd { id, label, menu, key, params, kind, run, undo: matches!(kind, K::Undo), query: matches!(kind, K::Query) }
}

fn nothing(_: &mut Engine, _: &Json) -> Res {
    Ok(Json::Null)
}

